cat >> tests/tasks.test.ts <<'EOF'

describe("SL-004 reject empty and over-long titles", () => {
  let server: Running;

  before(async () => {
    server = await startServer();
  });
  after(async () => {
    await server?.stop();
  });

  async function assertRejected(response: Response, code: string, message: string): Promise<void> {
    assert.equal(response.status, 400);
    assert.deepEqual(await response.json(), { error: { code, message } });
  }

  it("AC-1: an empty title answers 400 'A title is required.' and stores nothing", async () => {
    await assertRejected(await createTask(server, ""), "validation_failed", "A title is required.");
    assert.deepEqual(await listTasks(server), []);
  });

  it("AC-1: a title of only spaces and line breaks is rejected the same way", async () => {
    await assertRejected(
      await createTask(server, "  \n\t  "),
      "validation_failed",
      "A title is required.",
    );
    assert.deepEqual(await listTasks(server), []);
  });

  it("AC-2: a 501-character title is rejected with the too-long message and stores nothing", async () => {
    await assertRejected(
      await createTask(server, "a".repeat(501)),
      "validation_failed",
      "The title is too long (maximum 500 characters).",
    );
    assert.deepEqual(await listTasks(server), []);
  });

  it("AC-2: the length is measured after trimming", async () => {
    const response = await createTask(server, `  ${"a".repeat(500)}  `);
    assert.equal(response.status, 201);
    const { task } = (await response.json()) as { task: Task };
    assert.equal(task.title, "a".repeat(500));
  });

  it("AC-2: 500 characters are counted as characters, not UTF-16 units", async () => {
    const response = await createTask(server, "😀".repeat(500));
    assert.equal(response.status, 201);
    await assertRejected(
      await createTask(server, "😀".repeat(501)),
      "validation_failed",
      "The title is too long (maximum 500 characters).",
    );
  });

  it("a missing or non-string title is rejected with 'Title must be a string.'", async () => {
    for (const body of ["{}", "null", '{"title":42}', '{"title":null}', "[]"]) {
      const response = await fetch(`${server.baseUrl}/api/tasks`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body,
      });
      await assertRejected(response, "validation_failed", "Title must be a string.");
    }
  });

  it("a body that is not JSON is rejected with invalid_json", async () => {
    const response = await fetch(`${server.baseUrl}/api/tasks`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: "{nope",
    });
    await assertRejected(response, "invalid_json", "The request body is not valid JSON.");
  });

  it("AC-1: after a rejection, a corrected title is added normally", async () => {
    const before = (await listTasks(server)).length;
    assert.equal((await createTask(server, "")).status, 400);
    assert.equal((await createTask(server, "Buy milk")).status, 201);
    assert.equal((await listTasks(server)).length, before + 1);
  });

  describe("the page", () => {
    let html: string;
    let script: string;

    before(async () => {
      html = await (await fetch(`${server.baseUrl}/`)).text();
      script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    });

    it("AC-1: has an alert element with id form-message for the reason", () => {
      assert.match(html, /<[a-z]+(?=[^>]*id=["']form-message["'])(?=[^>]*role=["']alert["'])/);
    });

    it("AC-1: the script shows the server's error message and keeps the typed title on failure", () => {
      assert.match(script, /form-message/);
      assert.match(script, /response\.ok/);
      assert.match(script, /error\.message/);
      assert.doesNotMatch(script, /innerHTML/);
    });
  });
});
EOF
